arguments.command:
cd /home/runner/work/_wt-phoebe && cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *Username*) echo "x-access-token" ;;
  *Password*) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh
GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git -c credential.helper= push origin HEAD:refs/heads/friend/phoebe 2>&1 | tail -5
